WITH with_gaps AS (SELECT *, CASE WHEN started_at - LAG(started_at) OVER (PARTITION BY device ORDER BY started_at ASC, id ASC) > INTERVAL '30' DAY THEN 1 ELSE 0 END AS is_new_burst FROM sessions), sessions_sessions AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY device ORDER BY started_at ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM with_gaps) SELECT id, customer_id, device, browser, started_at, country, session_id, CASE WHEN device RLIKE '^(desktop|mobile)$' THEN 'EXTENDED' WHEN device RLIKE '^(tablet)$' THEN 'OTHER_ZONE' ELSE 'PRIORITY' END AS device_zone FROM sessions_sessions;
